import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-cDxYqO3U.js";var i=JSON.parse(`{"path":"/deploy/native/jwynt0v0/","title":"SmartDNS 部署与配置 | Native","lang":"zh-CN","frontmatter":{"title":"SmartDNS 部署与配置","createTime":"2026/08/26 15:37:34","permalink":"/deploy/native/jwynt0v0/"},"readingTime":{"minutes":2.31,"words":694},"git":{},"filePathRelative":"deploy/native/001.deploy-smartdns.md","headers":[]}`),a={name:`001.deploy-smartdns.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>SmartDNS 是一款本地 DNS 服务器，通过多上游并发查询、测速选快等机制提升 DNS 解析速度与准确性。本文记录在 Linux（x86 及 ARM/Debian 系）上安装 SmartDNS、检查并解决 53 端口冲突、修改上游配置、启动服务，并将局域网 DNS 请求转发至 SmartDNS 的完整流程。</p><p>官网：<a href="https://pymumu.github.io/smartdns/" target="_blank" rel="noopener noreferrer">https://pymumu.github.io/smartdns/</a></p><p>Github：<a href="https://github.com/pymumu/smartdns" target="_blank" rel="noopener noreferrer">https://github.com/pymumu/smartdns</a></p><h2 id="一、linux-安装" tabindex="-1"><a class="header-anchor" href="#一、linux-安装"><span>一、Linux 安装</span></a></h2><ol><li><p>标准 Linux 系统（X86 / X86_64），下载配套安装包并上传后执行：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zxf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns.1.yyyy.MM.dd-REL.x86_64-linux-all.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span></span></code></pre></div></li><li><p>树莓派或其他 Debian 系系统（ARM / ARM64），执行：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns.1.yyyy.MM.dd-REL.arm-debian-all.deb</span></span></code></pre></div></li></ol><h2 id="二、检查-53-端口占用" tabindex="-1"><a class="header-anchor" href="#二、检查-53-端口占用"><span>二、检查 53 端口占用</span></a></h2><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方法1（推荐）：直接显示占用53端口的进程信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :53</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方法2：使用 netstat 查看</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tulpn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :53</span></span></code></pre></div><div class="hint-container caution"><p class="hint-container-title">注意</p><p>在 Ubuntu 系统下，<code>systemd-resolved</code> 会占用 <code>TCP 53</code> 和 <code>UDP 53</code> 端口，需手动解决端口冲突或改 SmartDNS 监听端口。SmartDNS 日志位于 <code>/var/log/smartdns/smartdns.log</code>。</p></div><p><strong>方案一：关闭 DNS 存根监听器，使其不再监听 53 端口</strong></p><ol><li><p>修改配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf</span></span></code></pre></div></li><li><p>取消注释并修改以下行：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DNSStubListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=no</span></span></code></pre></div></li><li><p>重启 <code>systemd-resolved</code> 使配置生效：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div></li></ol><p><strong>方案二：关闭 <code>systemd-resolved</code> 服务</strong></p><ol><li><p>立即停止：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div></li><li><p>永久禁用：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div></li></ol><h2 id="三、修改配置" tabindex="-1"><a class="header-anchor" href="#三、修改配置"><span>三、修改配置</span></a></h2><p>安装完成后，配置 SmartDNS 的上游服务器。一般情况下只需增加 <code>server [IP]:port</code> 与 <code>server-tcp [IP]:port</code> 两项，并尽可能配置多个国内外上游。完整参数见官方配置文件说明。</p><p>编辑配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/smartdns/smartdns.conf</span></span></code></pre></div><p>配置包含如下基本内容：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定监听的端口号</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bind []:53</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定上游服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server 1.1.1.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server-tls 8.8.8.8</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定域名规则</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">address /example.com/1.2.3.4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">domain-rules /example.com/ -address 1.2.3.4</span></span></code></pre></div><h2 id="四、启动服务" tabindex="-1"><a class="header-anchor" href="#四、启动服务"><span>四、启动服务</span></a></h2><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns</span></span></code></pre></div><h2 id="五、将-dns-请求转发到-smartdns" tabindex="-1"><a class="header-anchor" href="#五、将-dns-请求转发到-smartdns"><span>五、将 DNS 请求转发到 SmartDNS</span></a></h2><p>修改本地路由器的 DNS 服务器，将其指向运行 SmartDNS 的主机（如树莓派）：</p><ul><li>登录本地路由器，为运行 SmartDNS 的设备分配静态 IP。</li><li>将 WAN 口或 DHCP 下发的 DNS 改为该设备 IP。</li></ul><div class="hint-container warning"><p class="hint-container-title">警告</p><ol><li>不同品牌路由器配置方式不同，请自行搜索对应方法。</li><li>华为等部分路由器不支持将 DNS 设为本地 IP，此时可改为在电脑或手机端手动指定 DNS 为该设备 IP。</li></ol></div><h2 id="六、检测服务是否配置成功" tabindex="-1"><a class="header-anchor" href="#六、检测服务是否配置成功"><span>六、检测服务是否配置成功</span></a></h2><p>执行如下命令：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nslookup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -querytype=ptr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smartdns</span></span></code></pre></div><p>查看结果中的 <code>name</code> 是否为 <code>smartdns</code> 或你的主机名，若是则表示生效：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>$ nslookup -querytype=ptr smartdns</span></span>
<span class="line"><span>Server:         192.168.1.1</span></span>
<span class="line"><span>Address:        192.168.1.1#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Non-authoritative answer:</span></span>
<span class="line"><span>smartdns        name = smartdns.</span></span></code></pre></div><h2 id="参考" tabindex="-1"><a class="header-anchor" href="#参考"><span>参考</span></a></h2><ul><li><a href="https://pymumu.github.io/smartdns/install/linux/" target="_blank" rel="noopener noreferrer">标准 Linux 系统 / 树莓派 - SmartDNS</a></li></ul>`,32)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};